<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\Template\Domain\ValueObject;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFail;
use Civi\Lughauth\Features\Document\Template\Domain\TemplateChannelOptions;

class TemplateChannelVO
{
  public static function fromString(string $value): TemplateChannelVO
  {
      $errorsList = new ConstraintFailList();
      $candidate = self::tryFrom($value, $errorsList);
      if ($errorsList->hasErrors()) {
        throw $errorsList->asConstraintException();
      }
      \assert($candidate instanceof TemplateChannelVO);
      return $candidate;
  }
  public static function from(TemplateChannelVO|TemplateChannelOptions $value): TemplateChannelVO
  {
    return self::fromUnsafe($value);
  }
  public static function tryFrom(mixed $value, ConstraintFailList $list): ?TemplateChannelVO
  {
    if ( $value instanceof TemplateChannelVO ) {
      // If is a ValueObject, its already validated... nothing to append
      return $value;
    } else if( is_string($value) ) {
      if ($typed = self::readFromString($value)) {
        return self::tryFrom($typed, $list);
      } else {
        $list->add(new ConstraintFail('wrong_format', ['channel'], [$value], ['TemplateChannelOptions']));
        return null;
      }
    } else if( is_a($value, TemplateChannelOptions::class)) {
      return new TemplateChannelVO($value);
    } else {
      $list->add(new ConstraintFail('wrong_type', ['channel'], [$value], ['TemplateChannelOptions']));
      return null;
    }
  }
  private static function readFromString(string $enumString): ?TemplateChannelOptions
  {
    if( in_array($enumString, ['MAIL', 'mail', 'mAIL'])) {
      return TemplateChannelOptions::MAIL;
    }
    if( in_array($enumString, ['SMS', 'sms', 'sMS'])) {
      return TemplateChannelOptions::SMS;
    }
    return null;  }
  private static function fromUnsafe(mixed $value): TemplateChannelVO
  {
    if ($value instanceof TemplateChannelVO) {
      // If is a ValueObject, its already validated
      return $value;
    } else {
      // If is not a ValueObject, validation is need and exception throw
      $errorsList = new ConstraintFailList();
      $candidate = self::tryFrom($value, $errorsList);
      if ($errorsList->hasErrors()) {
        throw $errorsList->asConstraintException();
      }
      \assert($candidate instanceof TemplateChannelVO);
      return $candidate;
    }
  }
  /**
   * private constructor to avoid build a value without all the rule validations.
   */
  private function __construct(
    private readonly TemplateChannelOptions $channel
  ) {
  }
  public function value(): TemplateChannelOptions
  {
    return $this->channel;
  }
  public function equals(?TemplateChannelVO $other): bool
  {
    return $this->value() == $other?->value();
  }
}
